INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/derivative-rules#1', 'calculus-derivatives/derivative-rules', 1, 'numeric', 'Using the power rule, what is d/dx[x⁵] evaluated at x = 2?', NULL, '80', 0.5, 'Power rule: d/dx[x⁵] = 5x⁴. At x = 2: 5 × 2⁴ = 5 × 16 = 80.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/derivative-rules#2', 'calculus-derivatives/derivative-rules', 2, 'mcq', 'What is the general form of the product rule for d/dx[u(x)v(x)]?', '["u''v + uv''","u''v''","uv'' − u''v","(u + v)''"]', '"u''v + uv''"', NULL, 'The product rule differentiates each factor in turn while holding the other fixed, then sums the two results: d/dx[uv] = u''v + uv''.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/derivative-rules#3', 'calculus-derivatives/derivative-rules', 3, 'numeric', 'For f(x) = x²(x+1), the product rule gives f''(x) = 2x(x+1) + x². What is f''(2)?', NULL, '16', 0.5, 'f''(2) = 2×2×(2+1) + 2² = 4×3 + 4 = 12 + 4 = 16. (Check: expanding first gives f(x) = x³+x², so f''(x) = 3x²+2x, and f''(2) = 3×4 + 2×2 = 12+4 = 16 — matches.)') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/derivative-rules#4', 'calculus-derivatives/derivative-rules', 4, 'mcq', 'What is the chain rule''s general form for d/dx[f(g(x))]?', '["f''(g(x)) · g''(x)","f''(x) · g''(x)","f(g''(x))","f''(x) + g''(x)"]', '"f''(g(x)) · g''(x)"', NULL, 'The chain rule differentiates the outer function at the inner function''s value, then multiplies by the inner function''s own derivative: d/dx[f(g(x))] = f''(g(x))·g''(x).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/derivative-rules#5', 'calculus-derivatives/derivative-rules', 5, 'numeric', 'For f(x) = (2x+1)³, the chain rule gives f''(x) = 6(2x+1)². What is f''(1)?', NULL, '54', 1, 'At x = 1: 2x+1 = 3, so f''(1) = 6 × 3² = 6 × 9 = 54.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/gradient-steepest-ascent#1', 'calculus-derivatives/gradient-steepest-ascent', 1, 'mcq', 'What does the gradient vector ∇f = (∂f/∂x, ∂f/∂y) point toward?', '["The direction of steepest ascent (fastest increase in f)","The direction of steepest descent (fastest decrease in f)","Always toward the origin","A direction unrelated to how f changes"]', '"The direction of steepest ascent (fastest increase in f)"', NULL, 'The gradient is defined so that it always points in the direction that increases f fastest; its magnitude is how steep that fastest direction is.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/gradient-steepest-ascent#2', 'calculus-derivatives/gradient-steepest-ascent', 2, 'numeric', 'For f(x,y) = x² + y², what is the x-component of ∇f at the point (4, 1)?', NULL, '8', 0.1, '∂f/∂x = 2x, so at x = 4: 2 × 4 = 8.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/gradient-steepest-ascent#3', 'calculus-derivatives/gradient-steepest-ascent', 3, 'numeric', 'For f(x,y) = x² + y², what is the y-component of ∇f at the point (4, 1)?', NULL, '2', 0.1, '∂f/∂y = 2y, so at y = 1: 2 × 1 = 2.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/gradient-steepest-ascent#4', 'calculus-derivatives/gradient-steepest-ascent', 4, 'numeric', 'For f(x,y) = x² + y², what is the magnitude ‖∇f‖ at the point (3, 4)?', NULL, '10', 0.2, '∇f = (2×3, 2×4) = (6, 8), so ‖∇f‖ = √(6² + 8²) = √(36 + 64) = √100 = 10.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/gradient-steepest-ascent#5', 'calculus-derivatives/gradient-steepest-ascent', 5, 'mcq', 'Gradient descent moves parameters in the direction of −∇f instead of +∇f because it wants to:', '["Minimize the function (go downhill)","Maximize the function (go uphill)","Keep the function''s value constant","Increase the learning rate automatically"]', '"Minimize the function (go downhill)"', NULL, '∇f points uphill (steepest ascent). Since training wants to minimize a loss function, it steps in the opposite direction, −∇f, which points downhill toward lower loss.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/partial-derivatives#1', 'calculus-derivatives/partial-derivatives', 1, 'mcq', 'What does the partial derivative ∂f/∂x measure?', '["The rate of change of f in the x-direction, holding y fixed","The rate of change of f in the y-direction, holding x fixed","The total change in f from any direction combined","The value of f when x = 0"]', '"The rate of change of f in the x-direction, holding y fixed"', NULL, 'A partial derivative treats every other variable as a constant and asks the ordinary one-variable derivative question for just the variable being differentiated with respect to.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/partial-derivatives#2', 'calculus-derivatives/partial-derivatives', 2, 'numeric', 'For f(x,y) = x² + y², what is ∂f/∂x evaluated at (x,y) = (3, 5)?', NULL, '6', 0.1, '∂f/∂x = 2x (the y² term is treated as a constant and vanishes when differentiating with respect to x), so at x = 3: 2 × 3 = 6. Note y''s value doesn''t matter here.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/partial-derivatives#3', 'calculus-derivatives/partial-derivatives', 3, 'numeric', 'For f(x,y) = x² + y², what is ∂f/∂y evaluated at (x,y) = (3, 5)?', NULL, '10', 0.1, '∂f/∂y = 2y, so at y = 5: 2 × 5 = 10.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/partial-derivatives#4', 'calculus-derivatives/partial-derivatives', 4, 'mcq', 'At the point (2, 0) on f(x,y) = x² + y², which partial derivative equals zero?', '["∂f/∂y","∂f/∂x","Both are zero","Neither is zero"]', '"∂f/∂y"', NULL, '∂f/∂x = 2x = 4 at x = 2, but ∂f/∂y = 2y = 0 at y = 0 — moving in the y-direction from (2,0) doesn''t change f to first order, since y = 0 sits at the bottom of that slice''s parabola.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/partial-derivatives#5', 'calculus-derivatives/partial-derivatives', 5, 'slider-match', 'For f(x,y) = x² + y², estimate ∂f/∂x at x = -1.5 (any value of y).', NULL, '-3', 0.3, '∂f/∂x = 2x, so at x = -1.5: 2 × (-1.5) = -3.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/slope-and-rate-of-change#1', 'calculus-derivatives/slope-and-rate-of-change', 1, 'mcq', 'What does the secant line through (x₀, f(x₀)) and (x₀+Δx, f(x₀+Δx)) approach as Δx → 0?', '["The tangent line at x₀","The x-axis","A vertical line through x₀","The y-intercept of f"]', '"The tangent line at x₀"', NULL, 'As Δx shrinks, the second point slides back along the curve to meet the first point, and the secant line''s slope converges to the instantaneous rate of change — the tangent line''s slope, f''(x₀).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/slope-and-rate-of-change#2', 'calculus-derivatives/slope-and-rate-of-change', 2, 'numeric', 'For f(x) = x², what is the secant slope between x₀ = 1 and x₀+Δx = 1.1 (so Δx = 0.1)?', NULL, '2.1', 0.02, 'f(1) = 1 and f(1.1) = 1.21, so the secant slope is (1.21 − 1) / 0.1 = 0.21 / 0.1 = 2.1 — already close to the analytic derivative f''(1) = 2.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/slope-and-rate-of-change#3', 'calculus-derivatives/slope-and-rate-of-change', 3, 'slider-match', 'For f(x) = x², use f''(x) = 2x to estimate the exact derivative at x₀ = -2.', NULL, '-4', 0.3, 'f''(x) = 2x, so f''(-2) = 2 × (-2) = -4.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/slope-and-rate-of-change#4', 'calculus-derivatives/slope-and-rate-of-change', 4, 'mcq', 'As Δx shrinks toward 0, the secant slope for f(x) = x² at x₀ = 1 approaches which value?', '["2","1","0","4"]', '"2"', NULL, 'The analytic derivative is f''(x) = 2x, so f''(1) = 2 — this is the limit the secant slope converges to as Δx → 0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-derivatives/slope-and-rate-of-change#5', 'calculus-derivatives/slope-and-rate-of-change', 5, 'numeric', 'For f(x) = x², what is the exact derivative f''(3)?', NULL, '6', 0.01, 'f''(x) = 2x, so f''(3) = 2 × 3 = 6.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/area-under-curve#1', 'calculus-integration/area-under-curve', 1, 'mcq', 'Which Riemann sum approximation does this playground''s rectangles use?', '["Right sum — each rectangle''s height is f at the right endpoint of its subinterval","Left sum — each rectangle''s height is f at the left endpoint of its subinterval","Midpoint sum — each rectangle''s height is f at the subinterval''s midpoint","Trapezoidal rule — each panel averages the left and right heights"]', '"Right sum — each rectangle''s height is f at the right endpoint of its subinterval"', NULL, 'The playground computes sum = Δx · Σ f(a + i·Δx) for i = 1..n — using the right endpoint of each subinterval as the rectangle''s height, hence ''right Riemann sum.''') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/area-under-curve#2', 'calculus-integration/area-under-curve', 2, 'numeric', 'For f(x) = x² + 1 on [0, 4], what is the exact value of ∫₀⁴ f(x) dx?', NULL, '25.3333', 0.02, 'An antiderivative of x² + 1 is F(x) = x³/3 + x. F(4) - F(0) = (64/3 + 4) - 0 = 64/3 + 12/3 = 76/3 ≈ 25.3333.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/area-under-curve#3', 'calculus-integration/area-under-curve', 3, 'numeric', 'Using the right Riemann sum with n = 4 rectangles (Δx = 1) for f(x) = x² + 1 on [0, 4], what area does it give?', NULL, '34', 0.1, 'Right endpoints are x = 1, 2, 3, 4 with heights f(1)=2, f(2)=5, f(3)=10, f(4)=17. Sum = 34, and Δx = 1, so the Riemann sum is 1 × 34 = 34.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/area-under-curve#4', 'calculus-integration/area-under-curve', 4, 'mcq', 'As n (the rectangle count) increases toward infinity, what happens to the right Riemann sum?', '["It converges to the exact definite integral, since each rectangle''s width shrinks toward 0","It diverges to infinity","It stays fixed at its n = 2 value","It oscillates randomly with no limit"]', '"It converges to the exact definite integral, since each rectangle''s width shrinks toward 0"', NULL, 'This convergence is literally the definition of the definite integral: ∫ₐᵇ f(x)dx = lim(n→∞) of the Riemann sum, as narrower rectangles trace the curve more and more exactly.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/area-under-curve#5', 'calculus-integration/area-under-curve', 5, 'mcq', 'f(x) = x² + 1 is strictly increasing on [0, 4]. How does its right Riemann sum compare to the true area, for any finite n?', '["It overestimates the true area, because each rectangle''s height comes from the larger right-hand value","It underestimates the true area, because right endpoints are always the smaller value","It always equals the true area exactly, regardless of n","The comparison depends on whether n is even or odd"]', '"It overestimates the true area, because each rectangle''s height comes from the larger right-hand value"', NULL, 'On an increasing function, the right endpoint of each subinterval is always its highest point, so every rectangle sits above the curve — consistent with the n=2 (44), n=4 (34), and n=8 (29.5) sums all landing above the exact 25.333.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/fundamental-theorem#1', 'calculus-integration/fundamental-theorem', 1, 'mcq', 'What does the Fundamental Theorem of Calculus say about A(x) = ∫ₐˣ f(t) dt?', '["A''(x) = f(x) — differentiating the accumulated-area function returns the original function","A(x) = f''(x) for every x","A(x) is always a constant, independent of x","A(x) can only ever be computed numerically, never in closed form"]', '"A''(x) = f(x) — differentiating the accumulated-area function returns the original function"', NULL, 'This is the precise statement of the theorem: the derivative of the ''running area'' function A(x) = ∫ₐˣ f(t)dt is f(x) itself — integration and differentiation undo each other.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/fundamental-theorem#2', 'calculus-integration/fundamental-theorem', 2, 'numeric', 'For f(t) = 2t with antiderivative F(t) = t², what is ∫₀³ 2t dt?', NULL, '9', 0.05, 'By the FTC, ∫₀³ 2t dt = F(3) - F(0) = 3² - 0² = 9 - 0 = 9.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/fundamental-theorem#3', 'calculus-integration/fundamental-theorem', 3, 'numeric', 'Using the same f(t) = 2t and F(t) = t², what is ∫₀⁵ 2t dt?', NULL, '25', 0.05, '∫₀⁵ 2t dt = F(5) - F(0) = 5² - 0² = 25.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/fundamental-theorem#4', 'calculus-integration/fundamental-theorem', 4, 'mcq', 'In the playground, what does the marked point F(x₀) on the right-hand plot represent?', '["The shaded area under f from 0 to x₀ on the left-hand plot","The slope of f at x₀","The value of f at x₀","The maximum value f ever reaches"]', '"The shaded area under f from 0 to x₀ on the left-hand plot"', NULL, 'F(x₀) is the antiderivative evaluated at x₀, which by the FTC equals ∫₀^x₀ f(t)dt — exactly the shaded area shown in the left-hand plot. That''s the visual link the two panels demonstrate.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/fundamental-theorem#5', 'calculus-integration/fundamental-theorem', 5, 'numeric', 'F(x) = x² is the antiderivative of f(x) = 2x. What is F''(x) at x = 3?', NULL, '6', 0.1, 'F''(x) = 2x for F(x) = x², so F''(3) = 6, which equals f(3) = 2(3) = 6 — the derivative of the accumulated-area function gives back the original function, as the FTC states.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/integration-in-ml#1', 'calculus-integration/integration-in-ml', 1, 'mcq', 'Why must a valid probability density function p(x) satisfy ∫₋∞^∞ p(x) dx = 1?', '["Because the probability that the random variable takes some value at all is 100%","Because p(x) must always be a linear function","Because otherwise p(x) would have to be negative somewhere","Because the mean of the distribution must equal 1"]', '"Because the probability that the random variable takes some value at all is 100%"', NULL, 'The total area under a density is the probability the variable falls somewhere in its whole domain — an event that always happens, so the probability, and thus the total area, must be exactly 1.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/integration-in-ml#2', 'calculus-integration/integration-in-ml', 2, 'numeric', 'For the standard normal density, what is P(-1 ≤ X ≤ 1), to two decimal places?', NULL, '0.68', 0.02, 'This is the well-known ''68-95-99.7 rule'': about 68.27% (≈0.68) of a standard normal distribution''s probability mass lies within 1 standard deviation of the mean.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/integration-in-ml#3', 'calculus-integration/integration-in-ml', 3, 'numeric', 'For the standard normal density, what is P(-2 ≤ X ≤ 2), to two decimal places?', NULL, '0.95', 0.02, 'By the 68-95-99.7 rule, about 95.45% (≈0.95) of the distribution''s mass lies within 2 standard deviations of the mean.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/integration-in-ml#4', 'calculus-integration/integration-in-ml', 4, 'mcq', 'What quantity does E[X] = ∫ x · p(x) dx compute?', '["The probability-weighted average value of X — its expected value","The total area under p(x)","The largest value X can possibly take","The variance of X"]', '"The probability-weighted average value of X — its expected value"', NULL, 'E[X] is the continuous analogue of a weighted average: instead of summing (value × probability) over a finite outcome list, you integrate (value × density) over the whole continuum of possible values.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('calculus-integration/integration-in-ml#5', 'calculus-integration/integration-in-ml', 5, 'numeric', 'The standard normal density is symmetric about x = 0, and essentially all of its mass lies within [-4, 4]. Approximately what is P(0 ≤ X ≤ 4)?', NULL, '0.5', 0.02, 'Symmetry puts exactly half of the total probability (which sums to 1) above x = 0 and half below. Since the tails beyond ±4 hold only about 0.0000633 of the mass, P(0 ≤ X ≤ 4) is essentially the full upper half, ≈ 0.5.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/activation-functions#1', 'classification-activations/activation-functions', 1, 'numeric', 'sigmoid(z) = 1 / (1 + e^-z). What is sigmoid(0)?', NULL, '0.5', 0.01, 'At z=0, e^-0 = 1, so sigmoid(0) = 1 / (1 + 1) = 1/2 = 0.5. This is why sigmoid''s decision boundary sits exactly at z=0: sigmoid(z) >= 0.5 whenever z >= 0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/activation-functions#2', 'classification-activations/activation-functions', 2, 'numeric', 'ReLU''s derivative is 1 for z > 0 and 0 for z <= 0. What is the derivative of ReLU at z = 3?', NULL, '1', 0.01, 'ReLU(z) = max(0, z). For any z > 0, ReLU behaves like the identity function y = z, whose slope is exactly 1 — so the derivative at z = 3 is 1.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/activation-functions#3', 'classification-activations/activation-functions', 3, 'numeric', 'What is the derivative of ReLU at z = -2?', NULL, '0', 0.01, 'For z <= 0, ReLU(z) = 0 is a flat constant line, so its slope — and therefore its derivative — is 0. This is also why ReLU neurons can ''die'': once z stays negative, the gradient flowing back through that neuron is permanently 0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/activation-functions#4', 'classification-activations/activation-functions', 4, 'numeric', 'tanh(z) = (e^z - e^-z) / (e^z + e^-z). What is tanh(0)?', NULL, '0', 0.01, 'At z=0, e^0 - e^-0 = 1 - 1 = 0, so the whole fraction is 0. Unlike sigmoid (which is centered at 0.5), tanh is zero-centered, which is one reason it''s often preferred for hidden layers.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/activation-functions#5', 'classification-activations/activation-functions', 5, 'mcq', 'Which statement correctly describes softmax(z) applied to a vector of logits?', '["Every output is positive and the full vector always sums to exactly 1","It squashes each entry independently into (0, 1), like applying sigmoid to each logit separately","It can produce negative probabilities when logits are negative","Only the single largest logit gets a nonzero output"]', '"Every output is positive and the full vector always sums to exactly 1"', NULL, 'softmax(z)_i = e^{z_i} / sum_j e^{z_j}. Every e^{z_i} is positive, and dividing by the shared sum of all of them forces the outputs to add up to exactly 1 — unlike sigmoid, softmax couples every output to every other logit through that shared denominator.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/logistic-regression#1', 'classification-activations/logistic-regression', 1, 'mcq', 'In P(y=1|x) = sigmoid(w1*x1 + w2*x2 + b), what exactly defines the decision boundary?', '["The set of points where w1*x1 + w2*x2 + b = 0, i.e. P(y=1|x) = 0.5","The set of points where P(y=1|x) = 1","The single point where x1 = x2","The y-intercept of the sigmoid curve itself"]', '"The set of points where w1*x1 + w2*x2 + b = 0, i.e. P(y=1|x) = 0.5"', NULL, 'sigmoid(z) = 0.5 exactly when z = 0. So the boundary between ''predict class 1'' and ''predict class 0'' is precisely the line w1*x1 + w2*x2 + b = 0 — everywhere else, the model leans toward one class or the other.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/logistic-regression#2', 'classification-activations/logistic-regression', 2, 'numeric', 'With w1=1, w2=1, b=-6, what is P(y=1|x) at x1=2, x2=2? (z = 1*2 + 1*2 - 6 = -2)', NULL, '0.119', 0.02, 'z = 1*2 + 1*2 - 6 = -2. sigmoid(-2) = 1 / (1 + e^2) = 1 / (1 + 7.389) ≈ 1 / 8.389 ≈ 0.119 — a low probability, correctly reflecting that (2,2) sits on the negative side of this boundary.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/logistic-regression#3', 'classification-activations/logistic-regression', 3, 'mcq', 'If w2 = 0, what does the boundary x2 = -(w1*x1 + b)/w2 turn into?', '["A vertical line x1 = -b/w1 (the equation no longer depends on x2 at all)","A horizontal line at x2 = 0","It disappears — there is no boundary","A single point at the origin"]', '"A vertical line x1 = -b/w1 (the equation no longer depends on x2 at all)"', NULL, 'With w2=0 the original equation is w1*x1 + b = 0, which has no x2 term at all — it''s satisfied by every x2 as long as x1 = -b/w1. Geometrically that''s a vertical line, which is also why the boundary formula x2 = -(w1*x1+b)/w2 divides by zero and must be guarded in code.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/logistic-regression#4', 'classification-activations/logistic-regression', 4, 'numeric', 'For the boundary x2 = -(w1*x1 + b)/w2 with w1=2, w2=1, b=-4, what is x2 when x1=0?', NULL, '4', 0.1, 'x2 = -(2*0 + (-4)) / 1 = -(-4) / 1 = 4. Plugging x1=0, x2=4 back into w1*x1+w2*x2+b gives 2*0 + 1*4 - 4 = 0, confirming that point sits exactly on the boundary.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/logistic-regression#5', 'classification-activations/logistic-regression', 5, 'mcq', 'If you scale w1, w2, and b all by the same large positive factor (keeping their ratios, and therefore the boundary line, fixed), what happens to the model''s predictions?', '["The sigmoid transition gets steeper — predictions near the boundary become more confident (closer to 0 or 1)","The decision boundary line itself shifts to a new location","Nothing changes at all, predictions are identical","Predictions become less confident everywhere"]', '"The sigmoid transition gets steeper — predictions near the boundary become more confident (closer to 0 or 1)"', NULL, 'Scaling w1, w2, b by a constant k doesn''t move the line w1*x1+w2*x2+b=0 (it''s still satisfied by the same points), but it multiplies the magnitude of z away from the boundary, pushing sigmoid(z) harder toward 0 or 1 — the model becomes more confident without becoming any more accurate.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/why-nonlinearity-matters#1', 'classification-activations/why-nonlinearity-matters', 1, 'mcq', 'Why can''t a single logistic regression unit correctly classify all 4 XOR points?', '["XOR''s two positive-class points and two negative-class points can''t be separated by any single straight line — the classes aren''t linearly separable","Logistic regression can only handle one input feature at a time","The sigmoid function isn''t smooth enough to fit 4 points","XOR only has 2 distinct points, not 4"]', '"XOR''s two positive-class points and two negative-class points can''t be separated by any single straight line — the classes aren''t linearly separable"', NULL, '(0,0) and (1,1) are label 0; (0,1) and (1,0) are label 1 — they sit on opposite diagonal corners of the unit square, interleaved. Any straight line you draw puts at least one same-label pair on opposite sides, because a linear model''s decision boundary is always a single straight line.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/why-nonlinearity-matters#2', 'classification-activations/why-nonlinearity-matters', 2, 'numeric', 'In the XOR dataset, what is the target label for input (1, 0)?', NULL, '1', 0.01, 'XOR (exclusive or) outputs 1 when exactly one of its two inputs is 1. Since x1=1 and x2=0 differ, XOR(1, 0) = 1.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/why-nonlinearity-matters#3', 'classification-activations/why-nonlinearity-matters', 3, 'numeric', 'In the XOR dataset, what is the target label for input (1, 1)?', NULL, '0', 0.01, 'XOR outputs 0 when both inputs are the same. Since x1=1 and x2=1 are equal, XOR(1, 1) = 0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/why-nonlinearity-matters#4', 'classification-activations/why-nonlinearity-matters', 4, 'mcq', 'What architectural change lets a small neural network solve XOR where plain logistic regression cannot?', '["Adding a hidden layer with a non-linear activation (like tanh) between the input and the output","Using a larger learning rate during gradient descent","Removing the bias term from the output neuron","Representing the weights with more decimal places"]', '"Adding a hidden layer with a non-linear activation (like tanh) between the input and the output"', NULL, 'A hidden layer with a non-linear activation lets the network transform the input space before the final linear boundary is drawn — the hidden units can bend space so that points that weren''t linearly separable in the original coordinates become separable in the transformed ones.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('classification-activations/why-nonlinearity-matters#5', 'classification-activations/why-nonlinearity-matters', 5, 'mcq', 'A [2, 1, 1] network (one hidden neuron, tanh then sigmoid) thresholds a single monotonic function of one linear combination of the inputs. What does this imply about solving XOR?', '["It still cannot solve XOR — thresholding a monotonic function of one linear combination is equivalent to a linear decision boundary","It can always solve XOR, because tanh is a non-linear function","It solves XOR only if trained with a high enough learning rate","It solves XOR automatically because it technically has a hidden layer"]', '"It still cannot solve XOR — thresholding a monotonic function of one linear combination is equivalent to a linear decision boundary"', NULL, 'With only one hidden neuron, the whole network output is sigmoid(v * tanh(w1x1+w2x2+b1) + b2). Since tanh and sigmoid are both strictly monotonic, this output crosses 0.5 along a curve that maps back to a single linear boundary in the original x1,x2 plane — one hidden neuron isn''t enough capacity, you need multiple hidden neurons combining in different directions.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/gradient-descent#1', 'core-ml-concepts/gradient-descent', 1, 'mcq', 'What does the learning rate control in gradient descent?', '["The size of each step taken in the direction opposite the gradient","The number of data points used per update","The final value the loss function must reach","The number of parameters in the model"]', '"The size of each step taken in the direction opposite the gradient"', NULL, 'The update rule θ ← θ − η·∇L scales the gradient step by η (the learning rate) — a bigger η means a bigger jump each iteration, regardless of how the model or data are structured.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/gradient-descent#2', 'core-ml-concepts/gradient-descent', 2, 'mcq', 'What typically happens when the learning rate is too high?', '["Parameters overshoot the minimum, and the loss oscillates or diverges","Training becomes perfectly stable and converges instantly","The gradient becomes exactly zero every step","The loss decreases monotonically but very slowly"]', '"Parameters overshoot the minimum, and the loss oscillates or diverges"', NULL, 'A step that''s too large in a steep direction jumps past the minimum to the opposite side — often further away than it started, so the next step overshoots even further, producing oscillation or outright divergence.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/gradient-descent#3', 'core-ml-concepts/gradient-descent', 3, 'mcq', 'What typically happens when the learning rate is too low?', '["Convergence is very slow, needing many more iterations to reach the minimum","The loss immediately diverges to infinity","The optimizer skips over the minimum entirely","The gradient''s sign flips every step"]', '"Convergence is very slow, needing many more iterations to reach the minimum"', NULL, 'Small steps are stable but make tiny progress each iteration — the trajectory still heads toward the minimum, it just takes far more iterations (and wall-clock time) to get there.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/gradient-descent#4', 'core-ml-concepts/gradient-descent', 4, 'numeric', 'Using gradient descent x ← x − η·(∂L/∂x) on L(x,y) = x² + 3y², at point (x,y) = (1,1) with η = 0.1, what is the new value of x after one step?', NULL, '0.8', 0.02, '∂L/∂x = 2x = 2(1) = 2. x_new = 1 − 0.1 × 2 = 1 − 0.2 = 0.8.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/gradient-descent#5', 'core-ml-concepts/gradient-descent', 5, 'numeric', 'Using the same setup — L(x,y) = x² + 3y² at (x,y) = (1,1) with η = 0.1 — what is the new value of y after one step?', NULL, '0.4', 0.02, '∂L/∂y = 6y = 6(1) = 6. y_new = 1 − 0.1 × 6 = 1 − 0.6 = 0.4 — y moves three times as far as x moved, because L is three times steeper along y.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/linear-regression#1', 'core-ml-concepts/linear-regression', 1, 'mcq', 'For a fitted line ŷ = mx + b, what do we call the difference (ŷᵢ − yᵢ) at a single data point?', '["The residual (error)","The gradient","The learning rate","The loss"]', '"The residual (error)"', NULL, 'The residual is the gap between the prediction and the actual value for one point. The loss (e.g. MSE) is a single number summarizing the residuals across every point, not one point''s residual.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/linear-regression#2', 'core-ml-concepts/linear-regression', 2, 'numeric', 'A line ŷ = 2x + 1 is used to predict a data point (x = 3, y = 5). What is the residual ŷ − y?', NULL, '2', 0.01, 'ŷ = 2(3) + 1 = 7, and the actual value is y = 5, so the residual is 7 − 5 = 2.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/linear-regression#3', 'core-ml-concepts/linear-regression', 3, 'numeric', 'Gradient descent updates a parameter via θ ← θ − η·(∂Loss/∂θ). If θ = 5, η (learning rate) = 0.1, and ∂Loss/∂θ = 20, what is θ after one update step?', NULL, '3', 0.01, 'θ_new = θ − η·gradient = 5 − 0.1 × 20 = 5 − 2 = 3.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/linear-regression#4', 'core-ml-concepts/linear-regression', 4, 'mcq', 'For MSE = (1/n)Σ(mxᵢ + b − yᵢ)², which expression is the correct partial derivative ∂MSE/∂m?', '["(2/n)Σ(mxᵢ + b − yᵢ)xᵢ","(2/n)Σ(mxᵢ + b − yᵢ)","(1/n)Σ(mxᵢ + b − yᵢ)²xᵢ","(2/n)Σxᵢ"]', '"(2/n)Σ(mxᵢ + b − yᵢ)xᵢ"', NULL, 'Applying the chain rule to (mxᵢ + b − yᵢ)² with respect to m: the outer derivative brings down a factor of 2(mxᵢ + b − yᵢ), and the inner derivative of (mxᵢ + b − yᵢ) with respect to m is xᵢ — giving (2/n)Σ(mxᵢ + b − yᵢ)xᵢ. (The ∂/∂b version drops the trailing xᵢ, since ∂(mxᵢ+b−yᵢ)/∂b = 1.)') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/linear-regression#5', 'core-ml-concepts/linear-regression', 5, 'numeric', 'For the two points (x=1, y=2) and (x=2, y=3), with a current fit ŷ = x (m=1, b=0), what is ∂MSE/∂b?', NULL, '-2', 0.05, 'Residuals: at x=1, ŷ=1 so error = 1−2 = −1; at x=2, ŷ=2 so error = 2−3 = −1. ∂MSE/∂b = (2/n)Σerror = (2/2)(−1 + −1) = −2.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/loss-functions#1', 'core-ml-concepts/loss-functions', 1, 'numeric', 'A model predicts [2, 4, 6, 8] for actual values [3, 5, 5, 20]. What is the MSE?', NULL, '36.75', 0.1, 'Errors are 2−3=−1, 4−5=−1, 6−5=1, 8−20=−12. Squared: 1, 1, 1, 144, summing to 147. MSE = 147/4 = 36.75.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/loss-functions#2', 'core-ml-concepts/loss-functions', 2, 'numeric', 'Using the same predictions [2, 4, 6, 8] and actual values [3, 5, 5, 20], what is the MAE?', NULL, '3.75', 0.1, 'Absolute errors are |−1|, |−1|, |1|, |−12| = 1, 1, 1, 12, summing to 15. MAE = 15/4 = 3.75 — far smaller than the MSE of 36.75, because MAE doesn''t square (and thus doesn''t amplify) the one large error.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/loss-functions#3', 'core-ml-concepts/loss-functions', 3, 'mcq', 'Compared to MAE, MSE is...', '["More sensitive to outliers, since errors are squared","Less sensitive to outliers, since errors are squared","Identical to MAE for every dataset","Undefined whenever an error is negative"]', '"More sensitive to outliers, since errors are squared"', NULL, 'Squaring an error of size k contributes k² to the sum, while MAE contributes only k — so as an error grows, MSE''s penalty grows much faster, letting a single outlier dominate the total loss.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/loss-functions#4', 'core-ml-concepts/loss-functions', 4, 'mcq', 'For a fixed set of values, which constant prediction c minimizes the mean absolute error (MAE)?', '["The median of the values","The mean of the values","The maximum value","The mode of the residuals"]', '"The median of the values"', NULL, 'MAE is minimized at the median because moving c past the median always increases the total absolute distance to at least half the points more than it decreases the distance to the other half — this is also why MAE is considered outlier-robust.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/loss-functions#5', 'core-ml-concepts/loss-functions', 5, 'numeric', 'For the values 3, 5, 5, 6, 20, what constant c minimizes the mean squared error (MSE)?', NULL, '7.8', 0.1, 'MSE is minimized by the mean: (3 + 5 + 5 + 6 + 20) / 5 = 39 / 5 = 7.8. Notice the outlier (20) pulls this MSE-optimal value well above the median of 5 — MSE''s optimum is dragged toward outliers, MAE''s is not.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/overfitting-underfitting#1', 'core-ml-concepts/overfitting-underfitting', 1, 'mcq', 'A degree-1 (linear) model fit to clearly curved data has high error on both the training data and new data. This is a classic sign of...', '["Underfitting (high bias)","Overfitting (high variance)","Perfect generalization","A learning rate that''s too high"]', '"Underfitting (high bias)"', NULL, 'The model is too simple (too few free parameters, or the wrong shape) to represent the true pattern — it''s systematically wrong everywhere, which is the definition of high bias.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/overfitting-underfitting#2', 'core-ml-concepts/overfitting-underfitting', 2, 'mcq', 'A degree-9 polynomial fit to only 16 noisy points achieves near-zero training loss but wiggles wildly between the points. This is a classic sign of...', '["Overfitting (high variance)","Underfitting (high bias)","Gradient explosion","A learning rate that''s too low"]', '"Overfitting (high variance)"', NULL, 'With enough free coefficients relative to the number of points, the model can curve through the noise itself rather than the underlying trend — it fits this particular training set extremely well but would fit a different noisy sample from the same distribution very differently (high variance across samples).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/overfitting-underfitting#3', 'core-ml-concepts/overfitting-underfitting', 3, 'mcq', 'For a fixed set of training points, as you raise the polynomial degree and refit by least squares each time, what happens to the training loss?', '["It decreases or stays the same — it never increases","It always increases","It stays exactly constant regardless of degree","It becomes undefined above degree 3"]', '"It decreases or stays the same — it never increases"', NULL, 'Every lower-degree polynomial is a special case of a higher-degree one (with the extra coefficients set to zero), so the higher-degree least-squares fit can always match or beat the lower-degree fit''s training loss — training loss alone can never tell you when you''ve started overfitting.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/overfitting-underfitting#4', 'core-ml-concepts/overfitting-underfitting', 4, 'mcq', 'Why is a model with very low training loss but poor performance on new, unseen data considered a problem, even though it fits the training data well?', '["It has memorized noise specific to the training set instead of learning the true underlying pattern, so it generalizes poorly","It ran out of gradient descent iterations before finishing","Training loss and test loss should always be numerically equal","It means the learning rate was set too high"]', '"It has memorized noise specific to the training set instead of learning the true underlying pattern, so it generalizes poorly"', NULL, 'The goal of a model is to perform well on new data, not just to minimize error on the exact points it was trained on — a large train/test performance gap is the signature of overfitting.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('core-ml-concepts/overfitting-underfitting#5', 'core-ml-concepts/overfitting-underfitting', 5, 'numeric', 'Fitting a degree-1 polynomial to a fixed noisy dataset gives training MSE ≈ 2.89. Fitting a degree-9 polynomial to the same points gives training MSE ≈ 0.04. Roughly how many times smaller is the degree-9 training loss than the degree-1 training loss (round to the nearest whole number)?', NULL, '72', 8, '2.89 ÷ 0.04 ≈ 72.25, so the degree-9 fit''s training loss is roughly 72 times smaller — exactly the always-decreasing-training-loss effect from question 3, here quantified.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/linear-functions#1', 'functions-graphs/linear-functions', 1, 'mcq', 'In y = mx + b, what does m represent?', '["The slope — the change in y per unit change in x","The y-intercept","The x-intercept","The maximum value of y"]', '"The slope — the change in y per unit change in x"', NULL, 'm is the rate of change: for every 1-unit increase in x, y changes by m.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/linear-functions#2', 'functions-graphs/linear-functions', 2, 'mcq', 'In y = mx + b, what does b represent?', '["The value of y when x = 0","The value of x when y = 0","The slope of the line","The steepness of the curve"]', '"The value of y when x = 0"', NULL, 'Substituting x = 0 into y = mx + b gives y = b — that''s the y-intercept.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/linear-functions#3', 'functions-graphs/linear-functions', 3, 'numeric', 'For y = 3x - 2, what is y when x = 4?', NULL, '10', 0.01, 'y = 3(4) - 2 = 12 - 2 = 10.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/linear-functions#4', 'functions-graphs/linear-functions', 4, 'numeric', 'A line passes through (0, 5) with slope -2. What is y when x = 3?', NULL, '-1', 0.01, 'y = mx + b = -2(3) + 5 = -6 + 5 = -1.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/linear-functions#5', 'functions-graphs/linear-functions', 5, 'numeric', 'What value of m makes y = mx + b a horizontal line?', NULL, '0', 0.001, 'When m = 0, y = b for every x — a horizontal line with zero slope.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/polynomials-exponentials-logarithms#1', 'functions-graphs/polynomials-exponentials-logarithms', 1, 'mcq', 'As x → ∞, which of these three eventually grows fastest?', '["x² (polynomial)","2^x (exponential)","log(x) (logarithm)","They all grow at the same rate"]', '"2^x (exponential)"', NULL, 'Exponential functions eventually overtake any polynomial, no matter how large the polynomial''s degree, because exponential growth compounds multiplicatively rather than additively.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/polynomials-exponentials-logarithms#2', 'functions-graphs/polynomials-exponentials-logarithms', 2, 'mcq', 'What is the domain of log_b(x) for b > 0, b ≠ 1?', '["All real numbers","x > 0","x ≥ 0","x ≠ 0"]', '"x > 0"', NULL, 'Logarithms are only defined for positive arguments — no real power of b produces zero or a negative number.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/polynomials-exponentials-logarithms#3', 'functions-graphs/polynomials-exponentials-logarithms', 3, 'numeric', 'Evaluate 2^5.', NULL, '32', 0.01, '2^5 = 2 × 2 × 2 × 2 × 2 = 32.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/polynomials-exponentials-logarithms#4', 'functions-graphs/polynomials-exponentials-logarithms', 4, 'numeric', 'Evaluate log₂(8) — what power of 2 gives 8?', NULL, '3', 0.01, '2³ = 8, so log₂(8) = 3.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/polynomials-exponentials-logarithms#5', 'functions-graphs/polynomials-exponentials-logarithms', 5, 'numeric', 'For f(x) = x^n (with coefficient a = 1), what value of n makes f(2) = 8?', NULL, '3', 0.01, '2³ = 8, so n = 3.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/what-is-a-function#1', 'functions-graphs/what-is-a-function', 1, 'mcq', 'What defines a function?', '["Each input maps to exactly one output","Each output maps to exactly one input","Inputs and outputs must both be positive","The graph must be a straight line"]', '"Each input maps to exactly one output"', NULL, 'By definition, a function assigns exactly one output to every input in its domain — this is what the graphical ''vertical line test'' checks for.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/what-is-a-function#2', 'functions-graphs/what-is-a-function', 2, 'mcq', 'Which of these sets of (input, output) pairs is NOT a function?', '["{(1,2), (2,4), (3,6)}","{(1,5), (2,5), (3,5)}","{(1,2), (1,-2), (2,4)}","{(0,0), (1,1), (2,4)}"]', '"{(1,2), (1,-2), (2,4)}"', NULL, 'The input 1 maps to two different outputs (2 and -2), which violates the one-output-per-input rule — the other options are all valid functions (many-to-one mappings are allowed).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/what-is-a-function#3', 'functions-graphs/what-is-a-function', 3, 'numeric', 'f(x) = 1/x is undefined at exactly one x-value. What is it?', NULL, '0', 0.001, 'Division by zero is undefined, so x = 0 must be excluded from the domain of f(x) = 1/x.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/what-is-a-function#4', 'functions-graphs/what-is-a-function', 4, 'numeric', 'What is the smallest value in the domain of f(x) = √x (restricting to real outputs)?', NULL, '0', 0.001, 'The square root of a negative number isn''t a real number, so the domain is x ≥ 0 — the smallest allowed value is 0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('functions-graphs/what-is-a-function#5', 'functions-graphs/what-is-a-function', 5, 'numeric', 'For f(x) = x², what positive value of x gives f(x) = 9?', NULL, '3', 0.01, '3² = 9. (-3 also satisfies x² = 9, but the question asked for the positive value.)') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/eigenvectors-eigenvalues#1', 'linear-algebra/eigenvectors-eigenvalues', 1, 'mcq', 'A vector v is an eigenvector of matrix A if...', '["Av = λv for some scalar λ (v''s direction is unchanged, only scaled)","Av = 0","A is symmetric","v has length exactly 1"]', '"Av = λv for some scalar λ (v''s direction is unchanged, only scaled)"', NULL, 'That''s the defining equation: transforming v by A produces a vector on the same line through the origin, merely scaled by λ (the eigenvalue).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/eigenvectors-eigenvalues#2', 'linear-algebra/eigenvectors-eigenvalues', 2, 'numeric', 'What is the larger eigenvalue of [[2, 1], [1, 2]]?', NULL, '3', 0.01, 'trace T = 4, det D = 4-1 = 3, discriminant = T² - 4D = 16-12 = 4, so λ = (4 ± 2)/2 = 3 or 1. The larger is 3.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/eigenvectors-eigenvalues#3', 'linear-algebra/eigenvectors-eigenvalues', 3, 'numeric', 'For matrix [[2, 1], [1, 2]] and eigenvector (1, -1), Av = λv. What is λ?', NULL, '1', 0.01, 'Av = (2·1 + 1·(-1), 1·1 + 2·(-1)) = (1, -1) = 1·(1, -1), so λ = 1.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/eigenvectors-eigenvalues#4', 'linear-algebra/eigenvectors-eigenvalues', 4, 'mcq', 'For a 2×2 matrix, the sum of the two eigenvalues always equals...', '["the trace (sum of the diagonal entries)","the determinant","zero","the largest matrix entry"]', '"the trace (sum of the diagonal entries)"', NULL, 'λ1 + λ2 = T (the trace) and λ1·λ2 = D (the determinant) — both fall directly out of the quadratic formula λ = (T ± √(T²-4D))/2.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/eigenvectors-eigenvalues#5', 'linear-algebra/eigenvectors-eigenvalues', 5, 'numeric', 'What is the determinant of [[2, 1], [1, 2]]?', NULL, '3', 0.01, 'det = (2)(2) - (1)(1) = 3. This also equals the product of the eigenvalues found earlier: 3 × 1 = 3.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-operations#1', 'linear-algebra/matrix-operations', 1, 'numeric', 'For A = [[1, 2], [3, 4]] and B = [[2, 0], [1, 2]], what is the top-left entry of AB?', NULL, '4', 0.01, '(AB)_11 = row 1 of A · column 1 of B = (1)(2) + (2)(1) = 2 + 2 = 4.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-operations#2', 'linear-algebra/matrix-operations', 2, 'mcq', 'For any matrix A and the identity matrix I, what is AI?', '["A","I","the zero matrix","A²"]', '"A"', NULL, 'The identity matrix is the multiplicative identity for matrices: AI = IA = A, always.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-operations#3', 'linear-algebra/matrix-operations', 3, 'numeric', 'What is the determinant of [[2, 4], [1, 2]]?', NULL, '0', 0.01, 'det = ad - bc = (2)(2) - (4)(1) = 4 - 4 = 0 — this matrix is singular (not invertible).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-operations#4', 'linear-algebra/matrix-operations', 4, 'mcq', 'A matrix with determinant 0 is...', '["not invertible (singular)","invertible, with an inverse equal to itself","always the identity matrix","guaranteed to be diagonal"]', '"not invertible (singular)"', NULL, 'The inverse formula divides by (ad - bc). When that''s 0, the division is undefined, matching the geometric fact that a det-0 matrix squashes the plane and destroys information that can''t be recovered.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-operations#5', 'linear-algebra/matrix-operations', 5, 'numeric', 'What is the bottom-right entry of the inverse of [[2, 0], [0, 4]]?', NULL, '0.25', 0.01, 'det = (2)(4) - (0)(0) = 8. Inverse = (1/8)[[4, 0], [0, 2]], so the bottom-right entry is 2/8 = 0.25.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-transformations#1', 'linear-algebra/matrix-transformations', 1, 'mcq', 'What does the matrix [[0, -1], [1, 0]] do to vectors?', '["Rotates them 90° counterclockwise","Rotates them 90° clockwise","Reflects them across the x-axis","Scales them by 2"]', '"Rotates them 90° counterclockwise"', NULL, 'Applied to (1,0): (0·1 + -1·0, 1·1 + 0·0) = (0, 1). The point on the positive x-axis moves to the positive y-axis, a 90° counterclockwise turn.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-transformations#2', 'linear-algebra/matrix-transformations', 2, 'numeric', 'Apply the matrix [[2, 0], [0, 3]] to the vector (4, 5). What is the x-coordinate of the result?', NULL, '8', 0.01, 'x'' = a·x + b·y = 2·4 + 0·5 = 8 (the y'' = 0·4 + 3·5 = 15 coordinate is scaled independently).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-transformations#3', 'linear-algebra/matrix-transformations', 3, 'mcq', 'A negative determinant indicates that the transformation...', '["flips orientation (mirrors the plane)","scales space uniformly in every direction","always rotates by exactly 180°","is guaranteed to not be invertible"]', '"flips orientation (mirrors the plane)"', NULL, 'The sign of the determinant tracks orientation: positive preserves it, negative flips it (like a reflection), independent of the magnitude |det| which gives the area scale factor.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-transformations#4', 'linear-algebra/matrix-transformations', 4, 'numeric', 'What is the determinant of [[3, 1], [2, 4]]?', NULL, '10', 0.01, 'det = ad - bc = (3)(4) - (1)(2) = 12 - 2 = 10.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/matrix-transformations#5', 'linear-algebra/matrix-transformations', 5, 'mcq', 'Under the shear matrix [[1, 1], [0, 1]], where does the point (0, 1) map to?', '["(1, 1)","(0, 1)","(1, 0)","(2, 1)"]', '"(1, 1)"', NULL, 'x'' = 1·0 + 1·1 = 1, y'' = 0·0 + 1·1 = 1, so (0,1) → (1,1) — a horizontal shear proportional to height.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/vectors#1', 'linear-algebra/vectors', 1, 'mcq', 'What is (2, 5) + (3, -1)?', '["(5, 4)","(1, 6)","(6, -5)","(5, -4)"]', '"(5, 4)"', NULL, 'Vector addition is component-wise: (2+3, 5+(-1)) = (5, 4).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/vectors#2', 'linear-algebra/vectors', 2, 'numeric', 'Compute the dot product of (3, 4) and (2, -1).', NULL, '2', 0.01, 'a·b = a_x b_x + a_y b_y = (3)(2) + (4)(-1) = 6 - 4 = 2.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/vectors#3', 'linear-algebra/vectors', 3, 'mcq', 'Two vectors are orthogonal (perpendicular) exactly when their dot product equals...', '["0","1","-1","the product of their magnitudes"]', '"0"', NULL, 'a·b = |a||b|cos(θ). At θ = 90°, cos(θ) = 0, so the dot product is 0 regardless of the vectors'' lengths.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/vectors#4', 'linear-algebra/vectors', 4, 'numeric', 'What is the magnitude (length) of the vector (3, 4)?', NULL, '5', 0.01, '|v| = sqrt(x^2 + y^2) = sqrt(9 + 16) = sqrt(25) = 5 — a 3-4-5 right triangle.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('linear-algebra/vectors#5', 'linear-algebra/vectors', 5, 'mcq', 'If vector v = (2, 3) is scaled by k = -2, the result is...', '["(-4, -6)","(4, 6)","(-4, 6)","(0, 1)"]', '"(-4, -6)"', NULL, 'kv = (kx, ky) = (-2·2, -2·3) = (-4, -6). A negative scalar also flips the vector''s direction.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/backpropagation-walkthrough#1', 'neural-networks/backpropagation-walkthrough', 1, 'mcq', 'What is the correct order of information flow in one backpropagation pass for a single training example?', '["Forward pass → loss → output-layer delta → output-layer gradients → backpropagate delta to hidden layer → hidden-layer gradients","Loss → forward pass → hidden-layer gradients → output-layer delta → backpropagate → output-layer gradients","Output-layer gradients → forward pass → hidden delta → loss → output delta → hidden gradients","All gradients are computed simultaneously in one independent step, with no ordering"]', '"Forward pass → loss → output-layer delta → output-layer gradients → backpropagate delta to hidden layer → hidden-layer gradients"', NULL, 'Backprop first runs the forward pass to get activations and the loss, computes the output layer''s delta from that loss, uses it for the output gradients, propagates the delta backward through the weights to get the hidden layer''s delta, then computes the hidden layer''s gradients from that.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/backpropagation-walkthrough#2', 'neural-networks/backpropagation-walkthrough', 2, 'numeric', 'For Sample A (input (0.05, 0.10), target 0.01) on the fixed 2-2-1 network, what is the output-layer delta δ^(2)? (For a sigmoid output with binary cross-entropy loss, δ^(2) = ŷ - y.)', NULL, '0.7414', 0.01, 'The forward pass gives ŷ ≈ 0.7514. δ^(2) = ŷ - y ≈ 0.7514 - 0.01 = 0.7414 — the sigmoid derivative and the BCE loss gradient''s denominator cancel exactly for this pairing, leaving prediction minus target.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/backpropagation-walkthrough#3', 'neural-networks/backpropagation-walkthrough', 3, 'mcq', 'What does a layer''s bias gradient ∂L/∂b equal, according to backpropagation?', '["That layer''s delta, exactly — no further multiplication needed","The weight gradient divided by the number of inputs","Always zero, since biases don''t affect the loss","The learning rate times the loss"]', '"That layer''s delta, exactly — no further multiplication needed"', NULL, 'Since z = Wx + b, ∂z/∂b = 1, so by the chain rule ∂L/∂b = ∂L/∂z · 1 = δ — the bias gradient is exactly the delta at that neuron.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/backpropagation-walkthrough#4', 'neural-networks/backpropagation-walkthrough', 4, 'mcq', 'How is a hidden neuron''s delta δ_i^(1) computed from the output layer''s delta?', '["Pull the output delta back through the weight connecting to that hidden neuron, then multiply by that neuron''s own local activation derivative","Copy the output delta unchanged to every hidden neuron","Multiply the output delta by the learning rate","Average the output delta with the loss"]', '"Pull the output delta back through the weight connecting to that hidden neuron, then multiply by that neuron''s own local activation derivative"', NULL, 'δ_i^(1) = (w_i^(2) · δ^(2)) · σ''(z_i^(1)) — the weight routes the output delta back to the specific hidden neuron it came from, and the local derivative accounts for that neuron''s own non-linearity.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/backpropagation-walkthrough#5', 'neural-networks/backpropagation-walkthrough', 5, 'slider-match', 'Sample B (input (2, 2), target 1) produces a prediction much closer to its target than Sample A does. Approximately what is δ^(2) for Sample B?', NULL, '-0.2208', 0.02, 'Sample B''s prediction (≈0.7792) is much closer to its target (1) than Sample A''s, so δ^(2) = ŷ - y ≈ 0.7792 - 1 = -0.2208 — a much smaller-magnitude error means a much smaller-magnitude gradient at that neuron.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/perceptron-to-mlp#1', 'neural-networks/perceptron-to-mlp', 1, 'mcq', 'What does a single perceptron with weights w1, w2 and bias b compute from inputs x1, x2?', '["σ(w1·x1 + w2·x2 + b) — a weighted sum passed through an activation function","The average of x1 and x2","w1·x1 · w2·x2 + b","The larger of x1 and x2, scaled by b"]', '"σ(w1·x1 + w2·x2 + b) — a weighted sum passed through an activation function"', NULL, 'A perceptron is a weighted sum (linear combination) of its inputs plus a bias, squashed by an activation function such as sigmoid — output = activation(w·x + b).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/perceptron-to-mlp#2', 'neural-networks/perceptron-to-mlp', 2, 'mcq', 'Why can a single perceptron never solve XOR, no matter how its weights are tuned?', '["Because XOR''s positive and negative points aren''t separable by any single straight line","Because sigmoid always outputs exactly 0.5","Because XOR needs three inputs instead of two","Because perceptrons can''t use a bias term"]', '"Because XOR''s positive and negative points aren''t separable by any single straight line"', NULL, 'A perceptron''s decision boundary (where z = 0) is always a straight line (or hyperplane in higher dimensions). XOR''s two positive points sit on opposite corners from its two negative points, so no single straight line can separate them — it isn''t linearly separable.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/perceptron-to-mlp#3', 'neural-networks/perceptron-to-mlp', 3, 'numeric', 'For a perceptron with w1 = 2, w2 = -1, b = 0.5 and input (x1, x2) = (1, 1), what is z = w1·x1 + w2·x2 + b?', NULL, '1.5', 0.01, 'z = 2(1) + (-1)(1) + 0.5 = 2 - 1 + 0.5 = 1.5.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/perceptron-to-mlp#4', 'neural-networks/perceptron-to-mlp', 4, 'numeric', 'Using z = 1.5 from the previous question, what is σ(z) = 1 / (1 + e^-z)?', NULL, '0.8176', 0.01, 'σ(1.5) = 1 / (1 + e^-1.5) = 1 / (1 + 0.2231) ≈ 0.8176.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/perceptron-to-mlp#5', 'neural-networks/perceptron-to-mlp', 5, 'mcq', 'What capability does stacking perceptrons into a multilayer network with non-linear activations between layers add, that a single perceptron lacks?', '["The ability to represent non-linearly-separable functions like XOR","Faster computation of purely linear functions","The ability to use negative weights","Removing the need for a bias term"]', '"The ability to represent non-linearly-separable functions like XOR"', NULL, 'Non-linear activations between stacked layers let the network bend and combine multiple straight-line boundaries into far more complex decision regions — enough to represent functions like XOR that no single line can separate.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/train-a-network#1', 'neural-networks/train-a-network', 1, 'mcq', 'In this playground, what typically happens if the learning rate is set far too high?', '["Training becomes unstable — the loss oscillates or diverges instead of steadily decreasing","The network trains in fewer steps with no downside","The architecture automatically simplifies itself","The dataset is regenerated with less noise"]', '"Training becomes unstable — the loss oscillates or diverges instead of steadily decreasing"', NULL, 'The learning rate scales the size of every SGD weight update. Too large a step can repeatedly overshoot the loss minimum, making the loss oscillate or blow up instead of converging smoothly.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/train-a-network#2', 'neural-networks/train-a-network', 2, 'mcq', 'Why does the spiral dataset typically need a larger or deeper architecture than XOR to classify well?', '["Its two interleaved arms form a far more complex, curved decision boundary that needs more representational capacity","It has fewer data points than XOR","It uses 3 input dimensions instead of 2","It uses a different loss function than XOR"]', '"Its two interleaved arms form a far more complex, curved decision boundary that needs more representational capacity"', NULL, 'XOR only needs a boundary separating 4 fixed corner points. Spiral''s two winding arms require a boundary complex enough to trace a spiral shape, which needs more hidden neurons and/or layers to represent.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/train-a-network#3', 'neural-networks/train-a-network', 3, 'mcq', 'In the network diagram, what do an edge''s color and thickness represent?', '["Color encodes the weight''s sign (positive vs. negative); thickness encodes |weight| (magnitude)","Color encodes the neuron''s activation function; thickness encodes the learning rate","Color encodes the training step number; thickness encodes dataset size","Color and thickness both encode the same value: the bias"]', '"Color encodes the weight''s sign (positive vs. negative); thickness encodes |weight| (magnitude)"', NULL, 'The diagram reads network.weights directly: hue distinguishes positive (indigo) from negative (amber) weights, and line thickness scales with the absolute value of the weight.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/train-a-network#4', 'neural-networks/train-a-network', 4, 'numeric', 'generateDataset(''circles'', ...) generates two concentric rings. What is the approximate (noise-free) radius of the inner ring — the one with label 0?', NULL, '0.5', 0.05, 'circlesDataset sets label 0''s base radius to 0.5 and label 1''s base radius to 1.0 (with small random noise added), producing two concentric rings scaled to roughly [-1, 1].') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('neural-networks/train-a-network#5', 'neural-networks/train-a-network', 5, 'mcq', 'If every hidden layer used a linear (identity) activation instead of tanh/relu, what would happen to the network''s representational power?', '["It would collapse to an equivalent single linear layer — stacking linear layers is still just linear","It would become strictly more powerful than any non-linear network","It would become unable to compute anything at all","It would stay exactly as powerful, since depth matters more than activation choice"]', '"It would collapse to an equivalent single linear layer — stacking linear layers is still just linear"', NULL, 'Composing linear transformations (matrix multiplications) always yields another linear transformation, no matter how many layers are stacked. The non-linear activation between layers is exactly what lets depth add representational power.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/distributions#1', 'probability-statistics/distributions', 1, 'mcq', 'For a continuous random variable, what does the total area under its PDF curve equal?', '["0","1","The mean of the distribution","The variance of the distribution"]', '"1"', NULL, 'A PDF must integrate to 1 over its whole domain — that''s what makes it a valid probability distribution (total probability across every possible outcome is 100%).') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/distributions#2', 'probability-statistics/distributions', 2, 'mcq', 'Which distribution is drawn as two bars — heights (1-p) and p — instead of a continuous curve?', '["Uniform","Normal","Bernoulli","Exponential"]', '"Bernoulli"', NULL, 'Bernoulli is discrete: X can only be 0 or 1, so it has a probability mass function (two bars summing to 1), not a probability density function.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/distributions#3', 'probability-statistics/distributions', 3, 'numeric', 'A uniform distribution is defined on [2, 6]. What is the constant height of its density p(x) on that interval?', NULL, '0.25', 0.02, 'p(x) = 1/(b-a) = 1/(6-2) = 1/4 = 0.25 for x in [2,6], and 0 outside it.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/distributions#4', 'probability-statistics/distributions', 4, 'numeric', 'For the standard normal distribution N(0,1), what is p(0) — the density at its peak?', NULL, '0.399', 0.01, 'p(0) = 1/(σ√(2π)) · e^0 = 1/(1·√(2π)) ≈ 1/2.5066 ≈ 0.3989 — this is the tallest point of the standard bell curve.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/distributions#5', 'probability-statistics/distributions', 5, 'mcq', 'For a normal distribution with μ fixed, what happens to the curve''s peak height as σ increases?', '["It gets taller and narrower","It gets shorter and wider","It stays exactly the same height","It shifts to the left"]', '"It gets shorter and wider"', NULL, 'The area under the curve must always stay 1. Spreading the distribution out (larger σ) means the peak height 1/(σ√(2π)) must shrink to keep the total area constant — width and height trade off against each other.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/expectation-variance-bayes#1', 'probability-statistics/expectation-variance-bayes', 1, 'mcq', 'Expanding Var(X) = E[(X - E[X])²] algebraically gives which equivalent shortcut formula?', '["E[X²] - E[X]²","E[X]² - E[X²]","E[X²] + E[X]²","2E[X] - E[X²]"]', '"E[X²] - E[X]²"', NULL, 'E[(X-μ)²] = E[X² - 2μX + μ²] = E[X²] - 2μE[X] + μ². Since E[X] = μ, that middle term is -2μ², leaving E[X²] - μ² = E[X²] - E[X]² — ''mean of the squares minus the square of the mean.''') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/expectation-variance-bayes#2', 'probability-statistics/expectation-variance-bayes', 2, 'numeric', 'A weighted die has outcomes 1, 2, 3, 4 with probabilities 0.1, 0.2, 0.3, 0.4. What is E[X]?', NULL, '3', 0.05, 'E[X] = 1(0.1) + 2(0.2) + 3(0.3) + 4(0.4) = 0.1 + 0.4 + 0.9 + 1.6 = 3.0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/expectation-variance-bayes#3', 'probability-statistics/expectation-variance-bayes', 3, 'numeric', 'For that same die (outcomes 1,2,3,4 with probabilities 0.1,0.2,0.3,0.4), what is Var(X)?', NULL, '1', 0.05, 'E[X²] = 1²(0.1) + 2²(0.2) + 3²(0.3) + 4²(0.4) = 0.1 + 0.8 + 2.7 + 6.4 = 10.0. Var(X) = E[X²] - E[X]² = 10.0 - 3.0² = 10.0 - 9.0 = 1.0.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/expectation-variance-bayes#4', 'probability-statistics/expectation-variance-bayes', 4, 'mcq', 'In the medical-test Bayes'' theorem scenario, what does ''sensitivity'', P(+|D), represent?', '["The probability a healthy person tests negative","The probability a diseased person tests positive","The overall probability of testing positive, healthy or not","The prior probability of having the disease"]', '"The probability a diseased person tests positive"', NULL, 'Sensitivity is a property of the test conditioned on actually having the disease: P(test positive | has disease). It says nothing on its own about P(disease | positive) — that requires Bayes'' theorem plus the prior.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/expectation-variance-bayes#5', 'probability-statistics/expectation-variance-bayes', 5, 'slider-match', 'Prior P(D) = 2%, sensitivity P(+|D) = 90%, false-positive rate P(+|¬D) = 10%. Estimate P(D|+) as a decimal (e.g. 0.20 for 20%).', NULL, '0.155', 0.02, 'P(+) = P(+|D)P(D) + P(+|¬D)P(¬D) = 0.9(0.02) + 0.1(0.98) = 0.018 + 0.098 = 0.116. P(D|+) = 0.018 / 0.116 ≈ 0.155 — despite a 90%-sensitive test, most positives are still false positives because the disease is rare.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/maximum-likelihood#1', 'probability-statistics/maximum-likelihood', 1, 'mcq', 'Intuitively, what does ''maximum likelihood estimation'' choose?', '["Parameters that make the observed data as probable as possible under the assumed model","Parameters that minimize how many data points are needed","The largest possible numeric value for every parameter","Random parameters, averaged over many trials"]', '"Parameters that make the observed data as probable as possible under the assumed model"', NULL, 'MLE asks ''which parameter values would have made the data I actually saw most likely to occur?'' and picks those — it''s fitting the model to the evidence, not to an arbitrary criterion.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/maximum-likelihood#2', 'probability-statistics/maximum-likelihood', 2, 'mcq', 'Why do we maximize the log-likelihood ln L instead of the raw likelihood L?', '["Because ln L is always a positive number","Because multiplying many small probabilities underflows toward 0 in floating point, while summing their logs doesn''t — and since ln is strictly increasing, the maximizer is unchanged","Because ln L is easier to plot on a graph","Because the raw likelihood always equals exactly 1"]', '"Because multiplying many small probabilities underflows toward 0 in floating point, while summing their logs doesn''t — and since ln is strictly increasing, the maximizer is unchanged"', NULL, 'Likelihood is a product of many densities, each typically well below 1, so it shrinks toward 0 numerically for even moderate sample sizes. Log-likelihood turns that product into a sum, which is numerically stable, and because ln() is monotonic it never moves the location of the maximum.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/maximum-likelihood#3', 'probability-statistics/maximum-likelihood', 3, 'numeric', 'For the 5 sample points {3, 4, 4, 6, 8}, what is the closed-form MLE estimate μ̂ (the sample mean)?', NULL, '5', 0.1, 'μ̂ = (3 + 4 + 4 + 6 + 8) / 5 = 25 / 5 = 5.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/maximum-likelihood#4', 'probability-statistics/maximum-likelihood', 4, 'numeric', 'For the same 5 points {3, 4, 4, 6, 8}, what is the closed-form MLE estimate σ̂ (standard deviation, dividing by n)?', NULL, '1.789', 0.1, 'Deviations from the mean (5) are -2, -1, -1, 1, 3; squared: 4, 1, 1, 1, 9, summing to 16. σ̂ = √(16/5) = √3.2 ≈ 1.789.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
INSERT INTO "questions" ("id", "quiz_id", "order", "kind", "prompt", "options", "correct_answer", "tolerance", "explanation") VALUES ('probability-statistics/maximum-likelihood#5', 'probability-statistics/maximum-likelihood', 5, 'slider-match', 'Using μ = 5 and σ = 1.8 (near the MLE optimum) for the points {3, 4, 4, 6, 8}, the log-likelihood ln L(μ,σ) is approximately what value?', NULL, '-10', 0.5, 'ln L = -n·ln(σ) - (n/2)·ln(2π) - Σ(xᵢ-μ)²/(2σ²) = -5·ln(1.8) - 2.5·ln(2π) - 16/(2·1.8²) ≈ -10.0. Moving μ or σ away from the sample mean/std in either direction makes this number more negative — it''s a genuine maximum.') ON CONFLICT("id") DO UPDATE SET "quiz_id" = excluded."quiz_id", "order" = excluded."order", "kind" = excluded."kind", "prompt" = excluded."prompt", "options" = excluded."options", "correct_answer" = excluded."correct_answer", "tolerance" = excluded."tolerance", "explanation" = excluded."explanation";
